"""Legacy-compatible Meridian CRM permission check."""

_VALID_ACTIONS = frozenset({"READ", "CREATE", "UPDATE", "DELETE", "EXPORT"})


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the requested action is permitted under legacy RBAC rules."""
    if action not in _VALID_ACTIONS:
        return False

    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        # ADMIN bypasses scope only; reaching here confirms the required row exists.
        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user_team == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user_id == record.get("OWNER_UID", "")
        return False

    return False
